#include <iostream>
#include <string>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n;
    string cows;
    in >> n >> cows;
    vector<int> left(n);
    int previous[2] = {-1, -1};
    for (int i = 0; i < n; ++i) {
        int breed = cows[i] == 'G' ? 0 : 1;
        left[i] = i - previous[breed] - 1;
        previous[breed] = i;
    }
    int next[2] = {n, n};
    long long answer = 0;
    for (int i = n - 1; i >= 0; --i) {
        int breed = cows[i] == 'G' ? 0 : 1;
        int right = next[breed] - i - 1;
        answer += 1LL * (left[i] + 1) * (right + 1) - 1;
        if (left[i] > 0) --answer;
        if (right > 0) --answer;
        next[breed] = i;
    }
    out << answer << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
