#include <cstdlib>
#include <iostream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n;
    in >> n;
    vector<long long> preferred(n);
    for (int i = 0; i < n; ++i) in >> preferred[i];
    long long previous = 0, variation = 0;
    for (int i = 0; i < n; ++i) {
        long long current;
        in >> current;
        long long difference = preferred[i] - current;
        variation += llabs(difference - previous);
        previous = difference;
    }
    variation += llabs(previous);
    out << variation / 2 << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
