#include <iostream>
#include <string>
#include <vector>
using namespace std;
long long countPaths(const vector<string>& grid, int limit) {
    int n = static_cast<int>(grid.size());
    long long ways[50][50][4][2] = {};
    if (grid[0][1] == '.') ways[0][1][0][0] = 1;
    if (grid[1][0] == '.') ways[1][0][0][1] = 1;
    const int dr[2] = {0, 1};
    const int dc[2] = {1, 0};
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            for (int turns = 0; turns <= limit; ++turns) {
                for (int last = 0; last < 2; ++last) {
                    long long value = ways[r][c][turns][last];
                    if (value == 0) continue;
                    for (int direction = 0; direction < 2; ++direction) {
                        int nr = r + dr[direction], nc = c + dc[direction];
                        int newTurns = turns + (direction != last);
                        if (nr < n && nc < n && grid[nr][nc] == '.' && newTurns <= limit)
                            ways[nr][nc][newTurns][direction] += value;
                    }
                }
            }
        }
    }
    long long answer = 0;
    for (int turns = 0; turns <= limit; ++turns)
        for (int last = 0; last < 2; ++last)
            answer += ways[n - 1][n - 1][turns][last];
    return answer;
}
void solve(istream& in, ostream& out) {
    int tests;
    in >> tests;
    while (tests--) {
        int n, limit;
        in >> n >> limit;
        vector<string> grid(n);
        for (int r = 0; r < n; ++r) in >> grid[r];
        out << countPaths(grid, limit) << '\n';
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
